    from biomart_workflow_evidence import verify
    proof=verify();assert proof['implementation_credit'] and proof['admitted_named_tools']==['biomart'];names=['papers.json','tool-inventory.json','summary.json','loftee-source-audit.json'];before={n:pin(data/n) for n in names};reviews_pin=pin(ROOT/'tools/literature/reviewed-uses.json');(out/'before-tool-inventory.json').write_bytes((data/'tool-inventory.json').read_bytes());save(out/'STARTED.json',dict(status='RUNNING_ONE_METADATA_ONLY_BIOMART_CATALOG_DELTA',before=before,reviews=reviews_pin))
    path=ROOT/'tools/literature/render_review.py';raw=path.read_bytes();(out/'before-render_review.py').write_bytes(raw);s=raw.decode('utf8');replacements=[('from loftee_catalog import (load_catalog_registry,','from biomart_catalog import (load_catalog_registry,'),('from loftee_catalog import soupx_metadata,','from biomart_catalog import soupx_metadata,'),('from loftee_catalog import smr_metadata, SMR_WARNING, SMR_ACTIONS','from biomart_catalog import smr_metadata, SMR_WARNING, SMR_ACTIONS'),('from loftee_catalog import loftee_metadata, LOFTEE_WARNING, LOFTEE_ACTIONS','from biomart_catalog import loftee_metadata, LOFTEE_WARNING, LOFTEE_ACTIONS\nfrom biomart_catalog import biomart_metadata, BIOMART_WARNING, BIOMART_ACTIONS'),('        elif tool_id == "loftee":','        elif tool_id == "biomart":\n            tool.update(biomart_metadata(ROOT,DATA))\n        elif tool_id == "loftee":'),('if tool_id not in {"loftee",','if tool_id not in {"biomart", "loftee",'),('write_text(LOFTEE_WARNING +','write_text(BIOMART_WARNING + LOFTEE_WARNING +'),('warning_body = LOFTEE_ACTIONS +','warning_body = BIOMART_ACTIONS + LOFTEE_ACTIONS +')]
